  object(value.target, ["board", "profile", "recipeIdentifier", "recipeSHA256", bindingKey], "$.target");
  for (const key of ["board", "profile"]) equal(value.target[key], NANO_BASELINE[key], `$.target.${key}`, "unsupported_target");
